import{_ as r,l as i,o as e,c as l,v as o,p as s,x as t,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"幌骚与分层","description":"","frontmatter":{"title":"幌骚与分层","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/spoofing-layering.md","filePath":"quant/spoofing-layering.md","lastUpdated":1789023840000}'),c={name:"quant/spoofing-layering.md"};function h(u,a,A,m,B,_){const n=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="幌骚与分层" tabindex="-1">幌骚与分层 <a class="header-anchor" href="#幌骚与分层" aria-label="Permalink to &quot;幌骚与分层&quot;">​</a></h1><div class="epigraph"><p>幌骚是提交无意成交的订单，制造虚假供需，诱使别人改价或吃单，再撤销并在相反方向获利。分层是在多个价位上铺开这些虚假供给。它们与做市闪单的分界，在意图与成交意愿，不在撤单率本身。</p><footer>—— Kyle and Viswanathan, How to Define Illegal Price Manipulation, American Economic Review, 2008；概述见 Putniņš, Market Manipulation: A Survey, Journal of Economic Surveys, 2012</footer></div><p><a href="/quant/quote-stuffing">报价填塞</a>攻击通道时钟。缺口是攻击<strong>别人对供需的信念</strong>：挂出不想成交的深度，让 Parlour 状态、宏观形状、甚至 Glosten 推断都读错。Kyle 与 Viswanathan（2008）给出操纵的经济学定义：扭曲价格并从自己造成的扭曲中获利。Putniņš（2012）综述操纵类型。本课写幌骚与分层的机制，不提供操作指南，也不把合法做市的偏度叫做操纵。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>可见簿是信号。若信号可被廉价伪造，理性交易者对深度打折，真实供给的价值下降，市场更依赖成交而不是报价来发现——效率与流动性都受损。幌骚的策略结构是：在一侧展示虚假厚单，诱使算法把中点或微观价格推向对侧，或诱使别人在对侧更积极地挂/吃，然后撤掉虚假单、自己在被推动的价格上成交。分层只是把虚假单铺在多档，让形状看起来「真实」。</p><p>问题是识别：与 Ho–Stoll 偏度（真想减库存而移动报价）、与隐藏（真有量不想展示）如何区分。关键是虚假侧在将要成交时是否系统性撤离，以及账户是否在对侧同步获利。</p><h3 id="法律与经济的接口" tabindex="-1">法律与经济的接口 <a class="header-anchor" href="#法律与经济的接口" aria-label="Permalink to &quot;法律与经济的接口&quot;">​</a></h3><p>商品与证券法规禁止欺诈性的虚假订单。经济学定义强调价格扭曲与自利交易，不一定要求「从未有过成交可能」。极薄市场上一张大单即使短暂真实，也可能以扭曲为目的。本课停在机制，不讨论个案。</p><p><span class="marginnote">冰山是隐藏真实量；幌骚是展示虚假量。方向相反。把冰山叫做操纵是范畴错误。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>研究常用账户层或标记数据：检测一侧大额新增随后在接近成交时撤销，对侧主动成交获利。分层看多档同时增、同时撤的相关性。市场质量：被操纵窗内价差、短期 VR、随后回复。理论把虚假深度写成对 \\(\\rho\\) 的扰动，别人的最优放置与市价阈值被误导，产生可预期的暂时价格，操纵者交易暂时成分——与 Grossman–Miller 的暂时折让同族，但是人为制造的 \\(z\\)。</p><p>检测的假阳性：正当事前撤单、新闻窗、pro-rata 堆量后撤余。必须结合对侧获利与模式重复。</p>',12)),(e(),s(E,null,{default:t(()=>[d(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20Fake%5B%22%E6%97%A0%E6%84%8F%E6%88%90%E4%BA%A4%E7%9A%84%E5%8F%AF%E8%A7%81%E6%B7%B1%E5%BA%A6%22%5D%20--%3E%20Bel%5B%22%E5%88%AB%E4%BA%BA%E6%9B%B4%E6%96%B0%E5%BD%A2%E7%8A%B6%20%2F%20%E4%B8%AD%E7%82%B9%22%5D%0A%20%20Bel%20--%3E%20Move%5B%22%E6%9A%82%E6%97%B6%E4%BB%B7%E6%A0%BC%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20Move%20--%3E%20Trade%5B%22%E5%AF%B9%E4%BE%A7%E7%9C%9F%E5%AE%9E%E6%88%90%E4%BA%A4%22%5D%0A%20%20Trade%20--%3E%20Cx%5B%22%E6%92%A4%E9%94%80%E8%99%9A%E5%81%87%E4%BE%A7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>幌骚剥削的是把 L2 当真实供给的算法与人。均场与宏观形状若被当成执行输入，正好成为受害者。对策是把可成交性放到事件流与自身的队列模型上，对突然出现、从不接近成交的远端厚单降权。做市商若无法区分真实需求，只能加宽——操纵的社会成本由所有人付更宽价差。</p><p>与狙击对照：狙击吃的是<strong>已经过时的真实报价</strong>；幌骚制造<strong>从未打算成为真实的报价</strong>。前者是连续时间优先的产物，后者是对透明的欺诈。政策工具不同：前者改协议时钟，后者靠监察与处罚。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>公开数据几乎看不见账户，学术检测受限。把「层层挂单」当成分层，会误伤正常的多档做市。教学案例（如被判决的期货幌骚）说明模式，不是数据课。加密市场操纵类型更多（洗售等），本课不展开。</p><p><span class="marginnote">交易台风控应把「对侧突然变厚却从不成交」当毒性信号，与 PIN 式买卖不平衡并列，而不是当额外流动性。</span></p><p>下一课回到真实供给：做市商在压力期关掉算法，空簿不必来自虚假挂单。操纵与撤退会在同一分钟里一起出现，会计上要分开谁制造了假深度、谁抽走了真深度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>幌骚与分层通过虚假可见供给扭曲他人信念，再交易由此产生的暂时价格。</li><li>与理性撤单、库存偏度、冰山隐藏的分界是成交意愿与对侧获利。</li><li>经济学定义见 Kyle–Viswanathan：扭曲并从扭曲中获利。</li><li>出处：Kyle and Viswanathan, <em>American Economic Review</em>, 2008；Putniņš, <em>Journal of Economic Surveys</em>, 2012。</li></ul>',9))])}const q=r(c,[["render",h]]);export{g as __pageData,q as default};
